class SetOperations:
    def __init__(self, *sets):
        self.sets = [set(s) for s in sets]

    def union(self):
        """
        Returns the union of all sets.
        """
        return set.union(*self.sets)

    def intersection(self):
        """
        Returns the intersection of all sets.
        """
        return set.intersection(*self.sets)

    def difference(self):
        """
        Returns the difference between the first set and the union of the other sets.
        """
        return {x for x in self.sets[0] if x not in self.union()}

    def symmetric_difference(self):
        """
        Returns the symmetric difference between all sets.
        """
        return set.symmetric_difference(*self.sets)


