        new_node = Node(data)
        if not self.tail:
            self.head = new_node
            self.tail = new_node
        else:
            new_node.prev = self.tail
            self.tail.next = new_node
            self.tail = new_node

    def remove_node(self, node):
        """Removes the first occurrence of the given node from the list."""
        if node == self.head:
            if node.next:
                self.head = node.next
                self.head.prev = None
