import random
import math

class Particle:
    def __init__(self, dim, min_val, max_val):
        self.position = [random.uniform(min_val, max_val) for _ in range(dim)]
        self.velocity = [0 for _ in range(dim)]
        self.best_position = self.position
        self.best_score = float('inf')

class PSO:
    def __init__(self, dim, pop_size, min_val, max_val, w, c1, c2):
        self.dim = dim
        self.pop_size = pop_size
        self.min_val = min_val
        self.max_val = max_val
        self.w = w
        self.c1 = c1
        self.c2 = c2
        self.pop = [Particle(dim, min_val, max_val) for _ in range(pop_size)]

    def evaluate(self, particle):
        score = particle.position[0] * math.sin(particle.position[1])
        return score

    def update_velocities(self, particle):
        for i in range(self.dim):
            r1, r2 = self.generate_r1_r2()
            cognitive_component = self.c1 * r1 * (particle.best_position[i] - particle.position[i])
            social_component = self.c2 * r2 * (self.get_global_best_position()[i] - particle.position[i])
            particle.velocity[i] = self.w * particle.velocity[i] + cognitive_component + social_component

    def update_positions(self, particle):
        for i in range(self.dim):
            particle.position[i] = particle.position[i] + particle.velocity[i]
            if particle.position[i] < self.min_val:
                particle.position[i] = self.min_val
            elif particle.position[i] > self.max_val:
                particle.position[i] = self.max_val

    def generate_r1_r2(self):
        r1 = random.random()
        r2 = random.random()
        return r1, r2

    def get_global_best_position(self):
        best_position = self.pop[0].best_position
        for particle in self.pop[1:]:
            if particle.best_position < best_position:
                best_position = particle.best_position
        return best_position

    def optimize(self):
        for _ in range(1000):
            for particle in self.pop:
                score = self.evaluate(particle)
                if score < particle.best_score:
                    particle.best_score = score
                    particle.best_position = particle.position
                self.update_velocities(particle)
                self.update_positions(particle)
        return self.get_global_best_position()

if __name__ == '__main__':
    pso = PSO(dim=2, pop_size=10, min_val=-10, max_val=10, w=0.7, c1=0.5, c2=0.3)
    print(pso.optimize())
